//! Effect-created "if a [nontoken] creature would enter and it wasn't cast, exile it
//! instead" — Mistcaller (activated, "Until end of turn") and Hallowed Moonlight (spell,
//! "Until end of turn"), sharing Containment Priest's builder through the
//! resolution-install front door `parse_windowed_enter_wasnt_cast_exile_install`.
//!
//! CR basis:
//! - CR 611.2a: the effect is generated by the resolving spell or ability and lasts as
//!   stated ("until end of turn"); CR 514.2 ends it in the cleanup step.
//! - CR 614.1a + CR 614.6: "instead" — the battlefield entry is replaced by a move to
//!   exile; the replaced event never happens.
//! - CR 614.12: the entering object is matched as it would exist on the battlefield.
//! - CR 113.7a: the activated ability (and its effect) is independent of Mistcaller, which
//!   was sacrificed as a cost.
//! - CR 601.2: casting; CR 305.1 + CR 305.9: playing a land is a special action, never a
//!   cast, so a played Dryad Arbor "wasn't cast".
//! - CR 701.7a + CR 111.7: creating a token is putting it onto the battlefield; a token
//!   moved elsewhere instead ceases to exist.
//! - CR 616.1 + CR 616.1f: with several applicable replacements the affected object's
//!   controller (or owner) chooses one; afterwards only the still-applicable ones remain.
//! - CR 707.9a + CR 707.9b: a copy exception is part of the copy's copiable values, so a
//!   copy token "except it's a ... creature" is a creature entering.
//!
//! Declared synthetic fixtures (labelled at each const) stand in for reanimation, flicker
//! and token makers; every named card is its verbatim Oracle text.

use std::ops::ControlFlow;

use engine::game::scenario::{GameRunner, GameScenario, P0, P1};
use engine::parser::oracle::{parse_oracle_text, ParsedAbilities};
use engine::types::ability::{
    AbilityCost, AbilityKind, ContinuousModification, Duration, Effect, FilterProp, TargetFilter,
};
use engine::types::ability_visit::visit_ability_def;
use engine::types::actions::GameAction;
use engine::types::card_type::CoreType;
use engine::types::game_state::{GameState, ReplacementChoiceKind, WaitingFor};
use engine::types::mana::{ManaCost, ManaType, ManaUnit};
use engine::types::phase::Phase;
use engine::types::player::PlayerId;
use engine::types::replacements::ReplacementEvent;
use engine::types::zones::Zone;
use engine::types::ObjectId;

// ---------------------------------------------------------------------------
// Verbatim Oracle text (Scryfall).
// ---------------------------------------------------------------------------

const MISTCALLER: &str = "Sacrifice this creature: Until end of turn, if a nontoken creature \
would enter and it wasn't cast, exile it instead.";

const HALLOWED_MOONLIGHT: &str = "Until end of turn, if a creature would enter and it wasn't \
cast, exile it instead.\nDraw a card.";

const CONTAINMENT_PRIEST: &str =
    "Flash\nIf a nontoken creature would enter and it wasn't cast, exile it instead.";

const DONT_BLINK: &str = "Until end of turn, if one or more creatures would enter from exile \
or after being cast from exile, their owners shuffle them into their libraries instead.\n\
Cycling {2} ({2}, Discard this card: Draw a card.)";

const JINNIE_FAY: &str = "If you would create one or more tokens, you may instead create that \
many 2/2 green Cat creature tokens with haste or that many 3/1 green Dog creature tokens with \
vigilance.";

const URZA_PRINCE_OF_KROOG: &str = "Artifact creatures you control get +2/+2.\n{6}: Create a \
token that's a copy of target artifact you control, except it's a 1/1 Soldier creature in \
addition to its other types.";

