/// DECLARED SYNTHETIC: Mistcaller's printed line minus its "Until end of turn," window
/// (P3).
const MISTCALLER_WITHOUT_WINDOW: &str = "Sacrifice this creature: If a nontoken creature would \
enter and it wasn't cast, exile it instead.";

/// DECLARED SYNTHETIC: reanimation — the creature is put onto the battlefield, never cast.
const REANIMATE: &str = "Return target creature card from your graveyard to the battlefield.";

/// DECLARED SYNTHETIC: steal-reanimation (owner differs from the new controller).
const STEAL_REANIMATE: &str =
    "Put target creature card from a graveyard onto the battlefield under your control.";

/// DECLARED SYNTHETIC: Cloudshift's text — exile, then return.
const FLICKER: &str =
    "Exile target creature you control, then return that card to the battlefield under your control.";

/// DECLARED SYNTHETIC token makers.
const MAKE_SOLDIER: &str = "Create a 1/1 white Soldier creature token.";
const MAKE_TREASURE: &str = "Create a Treasure token.";
const COPY_CREATURE: &str = "Create a token that's a copy of target creature you control.";
const COPY_ARTIFACT: &str = "Create a token that's a copy of target artifact you control.";
/// The exception phrase is Espers to Magicite's printed one.
const COPY_CREATURE_AS_ARTIFACT: &str = "Create a token that's a copy of target creature you \
control, except it's an artifact and it loses all other card types.";

/// The description the Mistcaller install carries: its clause after the window is peeled.
const MISTCALLER_CLAUSE: &str =
    "if a nontoken creature would enter and it wasn't cast, exile it instead";

// ---------------------------------------------------------------------------
// Helpers.
// ---------------------------------------------------------------------------

fn parse(oracle: &str, name: &str, types: &[&str], subtypes: &[&str]) -> ParsedAbilities {
    let types: Vec<String> = types.iter().map(|s| s.to_string()).collect();
    let subtypes: Vec<String> = subtypes.iter().map(|s| s.to_string()).collect();
    parse_oracle_text(oracle, name, &[], &types, &subtypes)
}

fn all_effects(parsed: &ParsedAbilities) -> Vec<Effect> {
    let mut collected = Vec::new();
    let mut visit = |effect: &Effect| {
        collected.push(effect.clone());
        ControlFlow::<()>::Continue(())
    };
    for def in &parsed.abilities {
        let _ = visit_ability_def(def, &mut visit);
    }
    collected
}

fn gaps(parsed: &ParsedAbilities) -> Vec<(String, Option<String>)> {
    all_effects(parsed)
        .into_iter()
        .filter_map(|effect| match effect {
            Effect::Unimplemented { name, description } => Some((name, description)),
            _ => None,
        })
        .collect()
}

/// A zero-cost instant parsed from `oracle`.
fn add_instant(
    scenario: &mut GameScenario,
    player: PlayerId,
    name: &str,
    oracle: &str,
) -> ObjectId {
    let mut card = scenario.add_spell_to_hand_from_oracle(player, name, true, oracle);
    card.with_mana_cost(ManaCost::generic(0));
    card.id()
}

fn add_mistcaller(scenario: &mut GameScenario) -> ObjectId {
    let mut card = scenario.add_creature_from_oracle(P0, "Mistcaller", 1, 1, MISTCALLER);
    card.with_subtypes(vec!["Merfolk", "Wizard"]);
    card.id()
}

fn add_dont_blink(scenario: &mut GameScenario) -> ObjectId {
    let mut card = scenario.add_spell_to_hand(P0, "Don't Blink", true);
    card.from_oracle_text_with_keywords(&["Cycling"], DONT_BLINK)
        .with_mana_cost(ManaCost::generic(0));
    card.id()
}

/// Dryad Arbor in `player`'s hand: Land Creature — Forest Dryad 1/1, no rules text beyond
/// reminder text.
fn add_dryad_arbor_to_hand(scenario: &mut GameScenario, player: PlayerId) -> ObjectId {
    let mut card = scenario.add_creature_to_hand(player, "Dryad Arbor", 1, 1);
    card.as_land()
        .as_creature()
        .with_subtypes(vec!["Forest", "Dryad"]);
    card.id()
}

fn base_scenario() -> GameScenario {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    scenario.with_library_top(P0, &["Island", "Island", "Island", "Island", "Island"]);
    scenario.with_library_top(P1, &["Island", "Island", "Island", "Island", "Island"]);
    scenario
}

fn assert_settled(state: &GameState, context: &str) {
    assert!(state.stack.is_empty(), "{context}: the stack must be empty");
    assert!(
        matches!(state.waiting_for, WaitingFor::Priority { .. }),
        "{context}: expected Priority, got {:?}",
        state.waiting_for
    );
}

fn activate_mistcaller(runner: &mut GameRunner, mistcaller: ObjectId) {
    let outcome = runner.activate(mistcaller, 0).resolve();
    // CR 113.7a: Mistcaller was sacrificed as a cost; its effect still exists.
    assert_eq!(
        outcome.zone_of(mistcaller),
        Zone::Graveyard,
        "Mistcaller is sacrificed as the activation cost"
    );
    assert_settled(outcome.state(), "Mistcaller activation");
}

fn cast_hallowed(runner: &mut GameRunner, hallowed: ObjectId) {
    let outcome = runner.cast(hallowed).resolve();
    outcome.assert_hand_drawn(P0, 1);
    assert_settled(outcome.state(), "Hallowed Moonlight");
}

fn battlefield_named(state: &GameState, name: &str) -> Vec<ObjectId> {
    state
        .battlefield
        .iter()
        .copied()
        .filter(|id| state.objects[id].name == name)
        .collect()
}

fn battlefield_tokens_named(state: &GameState, name: &str) -> Vec<ObjectId> {
    battlefield_named(state, name)
        .into_iter()
        .filter(|id| state.objects[id].is_token)
        .collect()
}

fn replacement_candidates(state: &GameState) -> (PlayerId, Vec<String>, ReplacementChoiceKind) {
    match &state.waiting_for {
        WaitingFor::ReplacementChoice {
            player,
            candidates,
            kind,
            ..
        } => (
            *player,
            candidates.iter().map(|c| c.description.clone()).collect(),
            *kind,
        ),
        other => panic!("expected WaitingFor::ReplacementChoice, got {other:?}"),
    }
}

// ---------------------------------------------------------------------------
// P1–P3 — parse rows.
// ---------------------------------------------------------------------------

/// P1. Mistcaller lowers to a floating "exile it instead" replacement carried by its
/// sacrifice-cost activated ability; the window travels on the ability's duration.
#[test]
fn mistcaller_parses_to_floating_enter_exile_install() {
    let parsed = parse(
        MISTCALLER,
        "Mistcaller",
        &["Creature"],
        &["Merfolk", "Wizard"],
    );
    assert!(gaps(&parsed).is_empty(), "no gaps, got {:?}", gaps(&parsed));
    assert_eq!(parsed.abilities.len(), 1);
    let ability = &parsed.abilities[0];
    assert_eq!(ability.kind, AbilityKind::Activated);
    assert!(
        matches!(ability.cost, Some(AbilityCost::Sacrifice(_))),
        "cost must be a sacrifice, got {:?}",
        ability.cost
    );
    assert_eq!(ability.duration, Some(Duration::UntilEndOfTurn));
    let Effect::AddTargetReplacement {
        replacement,
        target: TargetFilter::None,
    } = ability.effect.as_ref()
    else {
        panic!(
            "expected a floating AddTargetReplacement, got {:?}",
            ability.effect
        );
    };
    assert_eq!(replacement.event, ReplacementEvent::ChangeZone);
    assert_eq!(replacement.destination_zone, Some(Zone::Battlefield));
    assert_eq!(replacement.expiry, None);
    let Some(TargetFilter::Typed(filter)) = &replacement.valid_card else {
        panic!(
            "expected a typed valid_card, got {:?}",
            replacement.valid_card
        );
    };
    assert!(filter.properties.contains(&FilterProp::NonToken));
    assert!(filter.properties.contains(&FilterProp::Not {
        prop: Box::new(FilterProp::WasPlayed)
    }));
    let execute = replacement.execute.as_ref().expect("execute");
    assert!(
        matches!(
            execute.effect.as_ref(),
            Effect::ChangeZone {
                destination: Zone::Exile,
                target: TargetFilter::SelfRef,
                ..
            }
        ),
        "execute must exile the entering object, got {:?}",
        execute.effect
    );
    assert!(
        parsed.parse_warnings.is_empty(),
        "no swallowed clauses, got {:?}",
        parsed.parse_warnings
    );
}

/// P2. Hallowed Moonlight: the same install without `NonToken`, then "Draw a card."
#[test]
fn hallowed_moonlight_parses_to_floating_enter_exile_install_and_draw() {
    let parsed = parse(HALLOWED_MOONLIGHT, "Hallowed Moonlight", &["Instant"], &[]);
    assert!(gaps(&parsed).is_empty(), "no gaps, got {:?}", gaps(&parsed));
    let effects = all_effects(&parsed);
    assert!(
        effects.iter().any(|e| matches!(e, Effect::Draw { .. })),
        "reach-guard: line 2 still lowers to Draw"
    );
    let ability = &parsed.abilities[0];
    assert_eq!(ability.kind, AbilityKind::Spell);
    assert_eq!(ability.duration, Some(Duration::UntilEndOfTurn));
    let Effect::AddTargetReplacement {
        replacement,
        target: TargetFilter::None,
    } = ability.effect.as_ref()
    else {
        panic!(
            "expected a floating AddTargetReplacement, got {:?}",
            ability.effect
        );
    };
    let Some(TargetFilter::Typed(filter)) = &replacement.valid_card else {
        panic!(
            "expected a typed valid_card, got {:?}",
            replacement.valid_card
        );
    };
    assert!(
        !filter.properties.contains(&FilterProp::NonToken),
        "Hallowed Moonlight affects tokens too"
    );
    assert!(filter.properties.contains(&FilterProp::Not {
        prop: Box::new(FilterProp::WasPlayed)
    }));
}

/// P3. CR 611.2a: with no stated window the clause is not an effect created by
/// resolution, so the front door declines and the clause keeps its honest guard gap.
#[test]
fn unwindowed_enter_exile_clause_keeps_its_guard_gap() {
    let parsed = parse(
        MISTCALLER_WITHOUT_WINDOW,
        "Windowless Mistcaller",
        &["Creature"],
        &[],
    );
    assert!(
        !all_effects(&parsed)
            .iter()
            .any(|e| matches!(e, Effect::AddTargetReplacement { .. })),
        "no install without a stated window"
    );
    assert_eq!(
        gaps(&parsed),
        vec![(
            "unparsed_replacement".to_string(),
            Some(
                "If a nontoken creature would enter and it wasn't cast, exile it instead"
                    .to_string()
            )
        )],
        "exactly the clause's guard gap"
    );
}

