/// R1 + R2. After Mistcaller resolves (Mistcaller itself in the graveyard), a reanimated
/// nontoken creature is exiled instead; a creature spell that was cast enters normally.
#[test]
fn mistcaller_exiles_reanimated_creature_but_not_a_cast_one() {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let bear = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .id();
    let reanimate = add_instant(&mut scenario, P0, "Reanimate", REANIMATE);
    let mut giant = scenario.add_creature_to_hand(P0, "Hill Giant", 3, 3);
    giant.with_mana_cost(ManaCost::generic(0));
    let giant = giant.id();
    let mut runner = scenario.build();

    activate_mistcaller(&mut runner, mistcaller);

    let outcome = runner.cast(reanimate).target_object(bear).resolve();
    assert_eq!(
        outcome.zone_of(bear),
        Zone::Exile,
        "R1: a reanimated creature wasn't cast — exiled instead"
    );
    assert_settled(outcome.state(), "R1");

    let outcome = runner.cast(giant).resolve();
    assert_eq!(
        outcome.zone_of(giant),
        Zone::Battlefield,
        "R2: a cast creature spell enters normally"
    );
    assert_settled(outcome.state(), "R2");
}

/// R3. Owner ≠ controller: the stolen card is exiled into its owner's exile.
#[test]
fn mistcaller_exiles_stolen_reanimation_to_its_owner() {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let theirs = scenario
        .add_creature_to_graveyard(P1, "Craw Wurm", 6, 4)
        .id();
    let steal = add_instant(&mut scenario, P0, "Steal Reanimate", STEAL_REANIMATE);
    let mut runner = scenario.build();

    activate_mistcaller(&mut runner, mistcaller);
    let outcome = runner.cast(steal).target_object(theirs).resolve();
    assert_eq!(outcome.zone_of(theirs), Zone::Exile);
    assert_eq!(outcome.state().objects[&theirs].owner, P1);
    assert!(outcome.state().exile.contains(&theirs));
    assert_settled(outcome.state(), "R3");
}

/// R4. Mistcaller does not affect tokens; the effect is still live for nontoken entries.
#[test]
fn mistcaller_does_not_affect_tokens() {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let soldier = add_instant(&mut scenario, P0, "Make Soldier", MAKE_SOLDIER);
    let bear = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .id();
    let reanimate = add_instant(&mut scenario, P0, "Reanimate", REANIMATE);
    let mut runner = scenario.build();

    activate_mistcaller(&mut runner, mistcaller);
    let before = runner.battlefield_count(P0);
    let outcome = runner.cast(soldier).resolve();
    assert_settled(outcome.state(), "R4 soldier");
    assert_eq!(runner.battlefield_count(P0), before + 1, "the token enters");
    assert_eq!(battlefield_tokens_named(runner.state(), "Soldier").len(), 1);

    let outcome = runner.cast(reanimate).target_object(bear).resolve();
    assert_eq!(
        outcome.zone_of(bear),
        Zone::Exile,
        "reach-guard: the effect is live for a nontoken creature"
    );
}

/// R7. CR 514.2: the effect ends at cleanup; next turn a reanimated creature enters.
#[test]
fn mistcaller_effect_lapses_at_cleanup() {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let first = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .id();
    let reanimate = add_instant(&mut scenario, P0, "Reanimate", REANIMATE);
    let second = scenario
        .add_creature_to_graveyard(P1, "Craw Wurm", 6, 4)
        .id();
    let their_reanimate = add_instant(&mut scenario, P1, "Their Reanimate", REANIMATE);
    let mut runner = scenario.build();

    activate_mistcaller(&mut runner, mistcaller);
    let outcome = runner.cast(reanimate).target_object(first).resolve();
    assert_eq!(
        outcome.zone_of(first),
        Zone::Exile,
        "reach-guard: live this turn"
    );
    assert_eq!(
        mistcaller_install_description(runner.state()),
        MISTCALLER_CLAUSE,
        "reach-guard: the install is in the floating store before cleanup"
    );

    runner.advance_to_upkeep();
    assert_eq!(runner.state().phase, Phase::Upkeep);
    assert_eq!(runner.state().active_player, P1, "the next turn began");
    assert!(
        !runner
            .state()
            .pending_damage_replacements
            .iter()
            .any(|def| def.description.as_deref() == Some(MISTCALLER_CLAUSE)),
        "the install was pruned at cleanup"
    );

    let outcome = runner.cast(their_reanimate).target_object(second).resolve();
    assert_eq!(
        outcome.zone_of(second),
        Zone::Battlefield,
        "next turn creatures enter normally"
    );
    assert_settled(outcome.state(), "R7");
}

/// R8. Flicker under Mistcaller: the exile happens, the return is replaced by exile.
#[test]
fn mistcaller_keeps_a_flickered_creature_in_exile() {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let creature = scenario.add_creature(P0, "Grizzly Bears", 2, 2).id();
    let flicker = add_instant(&mut scenario, P0, "Flicker", FLICKER);
    let mut runner = scenario.build();

    activate_mistcaller(&mut runner, mistcaller);
    let outcome = runner.cast(flicker).target_object(creature).resolve();
    assert_eq!(outcome.zone_of(creature), Zone::Exile);
    assert!(battlefield_named(outcome.state(), "Grizzly Bears").is_empty());
    assert_settled(outcome.state(), "R8");
}

// ---------------------------------------------------------------------------
// R9 / R9h / R9cp — a land played as a land "wasn't cast" (CR 305.1 + CR 305.9).
// ---------------------------------------------------------------------------

fn play_land(runner: &mut GameRunner, land: ObjectId) {
    let card_id = runner.state().objects[&land].card_id;
    runner
        .act(GameAction::PlayLand {
            object_id: land,
            card_id,
        })
        .expect("Dryad Arbor is playable");
}

/// R9cp. Containment Priest (printed static) exiles a played Dryad Arbor. Pins the
/// stamp-after-delivery ordering the shared builder's `Not(WasPlayed)` gate relies on.
#[test]
fn containment_priest_exiles_played_dryad_arbor() {
    let mut scenario = base_scenario();
    scenario
        .add_creature(P0, "Containment Priest", 2, 2)
        .from_oracle_text_with_keywords(&["Flash"], CONTAINMENT_PRIEST);
    let arbor = add_dryad_arbor_to_hand(&mut scenario, P0);
    let mut runner = scenario.build();

    play_land(&mut runner, arbor);
    assert_eq!(
        runner.state().lands_played_this_turn,
        1,
        "reach-guard: the land play was accepted"
    );
    assert_eq!(runner.state().objects[&arbor].zone, Zone::Exile);
    assert_settled(runner.state(), "R9cp");
}

/// R9. Same under Mistcaller.
#[test]
fn mistcaller_exiles_played_dryad_arbor() {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let arbor = add_dryad_arbor_to_hand(&mut scenario, P0);
    let mut runner = scenario.build();

    activate_mistcaller(&mut runner, mistcaller);
    play_land(&mut runner, arbor);
    assert_eq!(runner.state().lands_played_this_turn, 1);
    assert_eq!(runner.state().objects[&arbor].zone, Zone::Exile);
    assert_settled(runner.state(), "R9");
}

/// R9h. Same under Hallowed Moonlight.
#[test]
fn hallowed_moonlight_exiles_played_dryad_arbor() {
    let mut scenario = base_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let arbor = add_dryad_arbor_to_hand(&mut scenario, P0);
    let mut runner = scenario.build();

    cast_hallowed(&mut runner, hallowed);
    play_land(&mut runner, arbor);
    assert_eq!(runner.state().lands_played_this_turn, 1);
    assert_eq!(runner.state().objects[&arbor].zone, Zone::Exile);
    assert_settled(runner.state(), "R9h");
}

// ---------------------------------------------------------------------------
// R5 / R5b / R5j / R5j-p — Hallowed Moonlight and tokens.
// ---------------------------------------------------------------------------

/// R5. Under Hallowed Moonlight a creature token that would be created is exiled
/// instead and never exists on the battlefield (CR 701.7a + CR 111.7); a noncreature
/// token, a cast creature spell and a reanimated card behave as the text says.
#[test]
fn hallowed_moonlight_exiles_creature_tokens() {
    let mut scenario = base_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let soldier = add_instant(&mut scenario, P0, "Make Soldier", MAKE_SOLDIER);
    let copy = add_instant(&mut scenario, P0, "Copy Creature", COPY_CREATURE);
    let treasure = add_instant(&mut scenario, P0, "Make Treasure", MAKE_TREASURE);
    let original = scenario.add_creature(P0, "Grizzly Bears", 2, 2).id();
    let mut giant = scenario.add_creature_to_hand(P0, "Hill Giant", 3, 3);
    giant.with_mana_cost(ManaCost::generic(0));
    let giant = giant.id();
    let dead = scenario
        .add_creature_to_graveyard(P0, "Craw Wurm", 6, 4)
        .id();
    let reanimate = add_instant(&mut scenario, P0, "Reanimate", REANIMATE);
    let mut runner = scenario.build();

    cast_hallowed(&mut runner, hallowed);
    let before = runner.battlefield_count(P0);

    let outcome = runner.cast(soldier).resolve();
    assert_settled(outcome.state(), "R5 soldier");
    assert!(battlefield_tokens_named(runner.state(), "Soldier").is_empty());
    assert_eq!(runner.battlefield_count(P0), before, "no Soldier entered");

    let outcome = runner.cast(copy).target_object(original).resolve();
    assert_settled(outcome.state(), "R5 copy");
    assert!(battlefield_tokens_named(runner.state(), "Grizzly Bears").is_empty());
    assert_eq!(
        runner.battlefield_count(P0),
        before,
        "no copy token entered"
    );

    let outcome = runner.cast(treasure).resolve();
    assert_settled(outcome.state(), "R5 treasure");
    assert_eq!(
        battlefield_tokens_named(runner.state(), "Treasure").len(),
        1,
        "a noncreature token is created normally"
    );

    let outcome = runner.cast(giant).resolve();
    assert_eq!(
        outcome.zone_of(giant),
        Zone::Battlefield,
        "cast creature enters"
    );

    let outcome = runner.cast(reanimate).target_object(dead).resolve();
    assert_eq!(
        outcome.zone_of(dead),
        Zone::Exile,
        "reanimated creature exiled"
    );
    assert_settled(outcome.state(), "R5");
}

/// R5b. CR 616.1 + CR 616.1f: with three Hallowed Moonlight installs, P0 chooses one
/// for the Soldier batch; once applied the batch puts nothing onto the battlefield, so
/// the other two no longer apply and no second choice is offered.
#[test]
fn three_hallowed_moonlights_prompt_once_for_a_token_batch() {
    let mut scenario = base_scenario();
    let first = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let second = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let third = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let soldier = add_instant(&mut scenario, P0, "Make Soldier", MAKE_SOLDIER);
    let mut runner = scenario.build();

    cast_hallowed(&mut runner, first);
    cast_hallowed(&mut runner, second);
    cast_hallowed(&mut runner, third);

    let outcome = runner.cast(soldier).resolve();
    let (player, candidates, _) = replacement_candidates(outcome.state());
    assert_eq!(player, P0);
    assert_eq!(candidates.len(), 3, "reach-guard: all three installs apply");

    runner
        .act(GameAction::ChooseReplacement { index: 0 })
        .expect("choice accepted");
    assert!(
        !matches!(
            runner.state().waiting_for,
            WaitingFor::ReplacementChoice { .. }
        ),
        "no second prompt once the batch is zeroed, got {:?}",
        runner.state().waiting_for
    );
    assert!(battlefield_tokens_named(runner.state(), "Soldier").is_empty());
    assert_settled(runner.state(), "R5b");
}

/// R5j. CR 616.1f + CR 614.6 + CR 701.7a: once Hallowed Moonlight's redirect has zeroed
/// the Soldier batch, Jinnie Fay's token-creation replacement no longer applies.
#[test]
fn hallowed_moonlight_applied_first_leaves_nothing_for_jinnie_fay() {
    let mut scenario = base_scenario();
    let mut jinnie =
        scenario.add_creature_from_oracle(P0, "Jinnie Fay, Jetmir's Second", 3, 3, JINNIE_FAY);
    jinnie.as_legendary().with_subtypes(vec!["Elf", "Druid"]);
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let soldier = add_instant(&mut scenario, P0, "Make Soldier", MAKE_SOLDIER);
    let mut runner = scenario.build();

    cast_hallowed(&mut runner, hallowed);
    let outcome = runner.cast(soldier).resolve();
    let (_, candidates, kind) = replacement_candidates(outcome.state());
    assert_eq!(kind, ReplacementChoiceKind::Order);
    assert_eq!(candidates.len(), 2, "reach-guard: both replacements apply");
    let jinnie_index = candidates
        .iter()
        .position(|d| d == JINNIE_FAY)
        .unwrap_or_else(|| panic!("one candidate is Jinnie Fay's, got {candidates:?}"));
    let hallowed_index = 1 - jinnie_index;

    runner
        .act(GameAction::ChooseReplacement {
            index: hallowed_index,
        })
        .expect("choice accepted");
    assert!(
        !matches!(
            runner.state().waiting_for,
            WaitingFor::ReplacementChoice { .. } | WaitingFor::ChooseOneOfBranch { .. }
        ),
        "Jinnie Fay must not apply to a zeroed batch, got {:?}",
        runner.state().waiting_for
    );
    for name in ["Soldier", "Cat", "Dog"] {
        assert!(
            battlefield_tokens_named(runner.state(), name).is_empty(),
            "no {name} token"
        );
    }
    assert_settled(runner.state(), "R5j");
}

/// R5j-p. Positive sibling: without Hallowed Moonlight, Jinnie Fay's optional
/// replacement is offered for the same live batch (the `count > 0` guard does not
/// refuse it). The row ends at that prompt: it is the claim.
#[test]
fn jinnie_fay_is_offered_for_a_live_token_batch() {
    let mut scenario = base_scenario();
    let mut jinnie =
        scenario.add_creature_from_oracle(P0, "Jinnie Fay, Jetmir's Second", 3, 3, JINNIE_FAY);
    jinnie.as_legendary().with_subtypes(vec!["Elf", "Druid"]);
    let soldier = add_instant(&mut scenario, P0, "Make Soldier", MAKE_SOLDIER);
    let mut runner = scenario.build();

    let outcome = runner.cast(soldier).resolve();
    let (player, candidates, kind) = replacement_candidates(outcome.state());
    assert_eq!(player, P0);
    assert_eq!(kind, ReplacementChoiceKind::OptionalBranch);
    assert!(
        candidates.iter().any(|d| d == JINNIE_FAY),
        "the offered replacement is Jinnie Fay's, got {candidates:?}"
    );
}

// ---------------------------------------------------------------------------
// R6 / R6b — two installs on one entry (CR 616.1).
// ---------------------------------------------------------------------------

/// R6. Hallowed Moonlight + Mistcaller on one reanimation: the owner chooses; after one
/// applies the other no longer applies; the card ends in exile once.
#[test]
fn two_identical_outcome_installs_prompt_once() {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let bear = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .id();
    let reanimate = add_instant(&mut scenario, P0, "Reanimate", REANIMATE);
    let mut runner = scenario.build();

    activate_mistcaller(&mut runner, mistcaller);
    cast_hallowed(&mut runner, hallowed);

    let outcome = runner.cast(reanimate).target_object(bear).resolve();
    let (player, candidates, _) = replacement_candidates(outcome.state());
    assert_eq!(player, P0);
    assert_eq!(candidates.len(), 2);

    runner
        .act(GameAction::ChooseReplacement { index: 0 })
        .expect("choice accepted");
    assert_eq!(runner.state().objects[&bear].zone, Zone::Exile);
    assert_settled(runner.state(), "R6");
}

/// The Mistcaller install's description, read from the floating store (the entry whose
/// execute sends the entrant to exile).
fn mistcaller_install_description(state: &GameState) -> String {
    let descriptions: Vec<String> = state
        .pending_damage_replacements
        .iter()
        .filter(|def| {
            def.execute.as_ref().is_some_and(|execute| {
                matches!(
                    execute.effect.as_ref(),
                    Effect::ChangeZone {
                        destination: Zone::Exile,
                        ..
                    }
                )
            })
        })
        .filter_map(|def| def.description.clone())
        .collect();
    assert_eq!(descriptions.len(), 1, "exactly one exile install");
    descriptions.into_iter().next().unwrap()
}

/// R6b setup: Don't Blink and Mistcaller installed, then flicker a P0-owned creature.
/// Returns the runner paused at the ordering prompt, the creature, and the index of the
/// Mistcaller candidate.
fn dont_blink_and_mistcaller_flicker() -> (GameRunner, ObjectId, usize) {
    let mut scenario = base_scenario();
    let mistcaller = add_mistcaller(&mut scenario);
    let dont_blink = add_dont_blink(&mut scenario);
    let creature = scenario.add_creature(P0, "Grizzly Bears", 2, 2).id();
    let flicker = add_instant(&mut scenario, P0, "Flicker", FLICKER);
    let mut runner = scenario.build();

    let outcome = runner.cast(dont_blink).resolve();
    assert_settled(outcome.state(), "Don't Blink");
    activate_mistcaller(&mut runner, mistcaller);
    let description = mistcaller_install_description(runner.state());

    let outcome = runner.cast(flicker).target_object(creature).resolve();
    let (player, candidates, _) = replacement_candidates(outcome.state());
    assert_eq!(player, P0);
    assert_eq!(candidates.len(), 2, "both installs apply to the return");
    let matching: Vec<usize> = candidates
        .iter()
        .enumerate()
        .filter(|(_, d)| **d == description)
        .map(|(i, _)| i)
        .collect();
    assert_eq!(
        matching.len(),
        1,
        "exactly one candidate is Mistcaller's: {candidates:?} vs {description:?}"
    );
    (runner, creature, matching[0])
}

/// R6b, run A. Choosing Don't Blink shuffles the creature into its owner's library;
/// Mistcaller then no longer applies (CR 616.1f).
#[test]
fn dont_blink_chosen_over_mistcaller_shuffles_the_creature() {
    let (mut runner, creature, mistcaller_index) = dont_blink_and_mistcaller_flicker();
    runner
        .act(GameAction::ChooseReplacement {
            index: 1 - mistcaller_index,
        })
        .expect("choice accepted");
    assert_eq!(runner.state().objects[&creature].zone, Zone::Library);
    assert_eq!(runner.state().objects[&creature].owner, P0);
    assert_settled(runner.state(), "R6b run A");
}

/// R6b, run B. Choosing Mistcaller exiles the creature; Don't Blink no longer applies.
#[test]
fn mistcaller_chosen_over_dont_blink_exiles_the_creature() {
    let (mut runner, creature, mistcaller_index) = dont_blink_and_mistcaller_flicker();
    runner
        .act(GameAction::ChooseReplacement {
            index: mistcaller_index,
        })
        .expect("choice accepted");
    assert_eq!(runner.state().objects[&creature].zone, Zone::Exile);
    assert_settled(runner.state(), "R6b run B");
}

// ---------------------------------------------------------------------------
// R10 / R10p / R10n / R10r — copy tokens and CR 707.9b exceptions.
// ---------------------------------------------------------------------------

const TRINKET: &str = "Ornate Trinket";

/// Urza on the battlefield with six colorless mana, plus a noncreature artifact to copy.
fn urza_scenario() -> (GameScenario, ObjectId, ObjectId) {
    let mut scenario = base_scenario();
    scenario.with_mana_pool(
        P0,
        (0..6)
            .map(|_| ManaUnit::new(ManaType::Colorless, ObjectId(0), false, vec![]))
            .collect(),
    );
    let mut urza =
        scenario.add_creature_from_oracle(P0, "Urza, Prince of Kroog", 2, 3, URZA_PRINCE_OF_KROOG);
    urza.as_legendary()
        .with_subtypes(vec!["Human", "Artificer"]);
    let urza = urza.id();
    let trinket = scenario.add_artifact_from_oracle(P0, TRINKET, "").id();
    (scenario, urza, trinket)
}

/// R10p. Reach-guard: without Hallowed Moonlight, Urza's activation creates exactly one
/// 1/1 Soldier artifact creature copy of the trinket.
#[test]
fn urza_copy_of_noncreature_artifact_is_an_artifact_creature() {
    let (scenario, urza, trinket) = urza_scenario();
    let mut runner = scenario.build();

    let outcome = runner.activate(urza, 0).target_object(trinket).resolve();
    assert_settled(outcome.state(), "R10p");
    let tokens = battlefield_tokens_named(outcome.state(), TRINKET);
    assert_eq!(tokens.len(), 1, "exactly one copy token");
    let token = &outcome.state().objects[&tokens[0]];
    assert!(token.card_types.core_types.contains(&CoreType::Artifact));
    assert!(token.card_types.core_types.contains(&CoreType::Creature));
    assert!(token.card_types.subtypes.iter().any(|s| s == "Soldier"));
}

/// R10. Under Hallowed Moonlight, Urza's copy is a creature (CR 707.9b), so it is exiled
/// instead and never created.
#[test]
fn hallowed_moonlight_exiles_copy_made_a_creature_by_its_exception() {
    let (mut scenario, urza, trinket) = urza_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let mut runner = scenario.build();

    cast_hallowed(&mut runner, hallowed);
    let before = runner.battlefield_count(P0);
    let outcome = runner.activate(urza, 0).target_object(trinket).resolve();
    assert_settled(outcome.state(), "R10");
    assert!(
        battlefield_tokens_named(outcome.state(), TRINKET).is_empty(),
        "the artifact creature copy must never be created"
    );
    assert_eq!(runner.battlefield_count(P0), before);
}

/// R10n. Sibling: an exception-free copy of the same noncreature artifact is not a
/// creature, so Hallowed Moonlight leaves it alone.
#[test]
fn hallowed_moonlight_keeps_exception_free_noncreature_copy() {
    let (mut scenario, _urza, trinket) = urza_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let copy = add_instant(&mut scenario, P0, "Copy Artifact", COPY_ARTIFACT);
    let dead = scenario
        .add_creature_to_graveyard(P0, "Grizzly Bears", 2, 2)
        .id();
    let reanimate = add_instant(&mut scenario, P0, "Reanimate", REANIMATE);
    let mut runner = scenario.build();

    cast_hallowed(&mut runner, hallowed);
    let outcome = runner.cast(copy).target_object(trinket).resolve();
    assert_settled(outcome.state(), "R10n copy");
    let tokens = battlefield_tokens_named(outcome.state(), TRINKET);
    assert_eq!(tokens.len(), 1, "the noncreature copy is created");
    assert!(!outcome.state().objects[&tokens[0]]
        .card_types
        .core_types
        .contains(&CoreType::Creature));

    let outcome = runner.cast(reanimate).target_object(dead).resolve();
    assert_eq!(
        outcome.zone_of(dead),
        Zone::Exile,
        "reach-guard: Hallowed Moonlight's effect is live"
    );
}

/// R10r. Reverse direction: a copy of a creature whose exception makes it a noncreature
/// artifact (CR 707.9b) is not a creature entering, so it is created.
#[test]
fn hallowed_moonlight_keeps_copy_made_a_noncreature_by_its_exception() {
    // Shape check first: the fixture carries exactly the SetCardTypes exception.
    let parsed = parse(
        COPY_CREATURE_AS_ARTIFACT,
        "Copy As Artifact",
        &["Instant"],
        &[],
    );
    assert!(gaps(&parsed).is_empty(), "no gaps, got {:?}", gaps(&parsed));
    let Effect::CopyTokenOf {
        additional_modifications,
        ..
    } = parsed.abilities[0].effect.as_ref()
    else {
        panic!("expected CopyTokenOf, got {:?}", parsed.abilities[0].effect);
    };
    assert_eq!(
        additional_modifications,
        &vec![ContinuousModification::SetCardTypes {
            core_types: vec![CoreType::Artifact],
        }]
    );

    let mut scenario = base_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let copy = add_instant(
        &mut scenario,
        P0,
        "Copy As Artifact",
        COPY_CREATURE_AS_ARTIFACT,
    );
    let original = scenario.add_creature(P0, "Grizzly Bears", 2, 2).id();
    let dead = scenario
        .add_creature_to_graveyard(P0, "Craw Wurm", 6, 4)
        .id();
    let reanimate = add_instant(&mut scenario, P0, "Reanimate", REANIMATE);
    let mut runner = scenario.build();

    cast_hallowed(&mut runner, hallowed);
    let outcome = runner.cast(copy).target_object(original).resolve();
    assert_settled(outcome.state(), "R10r copy");
    let tokens = battlefield_tokens_named(outcome.state(), "Grizzly Bears");
    assert_eq!(tokens.len(), 1, "the noncreature copy is created");
    assert_eq!(
        outcome.state().objects[&tokens[0]].card_types.core_types,
        vec![CoreType::Artifact]
    );

    let outcome = runner.cast(reanimate).target_object(dead).resolve();
    assert_eq!(
        outcome.zone_of(dead),
        Zone::Exile,
        "reach-guard: Hallowed Moonlight's effect is live"
    );
}
